<?php $root=base_url('store/'.($settings->store_slug ?? '')); ?>
<section class="mp-portal"><p class="mp-portal-kicker"><?= htmlspecialchars($store->store_name ?? 'Your store'); ?> · Your account</p><h1>Your orders.</h1><p class="mp-portal-intro">Review purchases and follow their progress.</p><nav class="mp-portal-actions"><a href="<?= $root.'/account'; ?>">← Your account</a><a href="<?= $root.'/products'; ?>">Continue shopping ↗</a></nav>
